package com.rationportal.service; import com.rationportal.model.OnorcPortability; import com.rationportal.repository.OnorcPortabilityRepository; import com.rationportal.repository.RationCardRepository; import com.rationportal.model.RationCard; import org.springframework.stereotype.Service; import java.util.UUID; @Service public class OnorcPortabilityService { private final OnorcPortabilityRepository repo; private final RationCardRepository rationCardRepo; public OnorcPortabilityService(OnorcPortabilityRepository repo,RationCardRepository rationCardRepo){this.repo=repo;this.rationCardRepo=rationCardRepo;} public OnorcPortability create(OnorcPortability p,String email){String card=p.getRationCardNumber()==null?"":p.getRationCardNumber().trim(); RationCard cardData=rationCardRepo.findByRationCardNumber(card).orElseThrow(()->new IllegalArgumentException("Ration card not found.")); if(cardData.getState()!=null&&!cardData.getState().isBlank())p.setHomeState(cardData.getState()); if(cardData.getDistrict()!=null&&!cardData.getDistrict().isBlank())p.setHomeDistrict(cardData.getDistrict()); p.setRationCardNumber(card); p.setReferenceNumber("ONORC"+UUID.randomUUID().toString().replace("-","").substring(0,10).toUpperCase()); p.setRequestedBy(email.toLowerCase()); p.setStatus("REQUESTED"); return repo.save(p);} }
